package com.fakelegacy.order.legacy;

import java.util.List;

import com.fakelegacy.order.domain.Order;

/**
 * Nightly CSV export for the accounting team. DO NOT REMOVE - used by batch.
 */
public class OrderExporterCsv {

    private static final String SEPARATOR = ";";

    // FIXME: amounts are exported with a comma on the accounting side, check the locale
    public String export(List<Order> orders) {
        StringBuilder sb = new StringBuilder("reference;customer;status;total\n");
        for (Order o : orders) {
            sb.append(o.getReference()).append(SEPARATOR)
                    .append(o.getCustomerId()).append(SEPARATOR)
                    .append(o.getStatus()).append(SEPARATOR)
                    .append(o.getTotalTtc()).append('\n');
        }
        return sb.toString();
    }
}
